<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Workboard</title>
    <link rel="stylesheet" href="/styles.css">
    <script src="/app.js" defer></script>
  </head>
  <body>
    <main class="shell">
      <header class="topbar"><a class="brand" href="/">Workboard</a></header>
      <section id="content" aria-live="polite"></section>
    </main>
  </body>
</html>
:root { color-scheme: light; font-family: system-ui, sans-serif; color: #172033; background: #f4f6fa; }
* { box-sizing: border-box; }
body { margin: 0; }
.shell { max-width: 780px; margin: 0 auto; padding: 0 24px 56px; }
.topbar { height: 72px; display: flex; align-items: center; border-bottom: 1px solid #dce1eb; }
.brand { color: #263d70; font-size: 19px; font-weight: 700; text-decoration: none; }
#content { padding-top: 36px; }
h1 { margin: 0 0 24px; font-size: 30px; }
.create-form { display: grid; grid-template-columns: 1fr auto; gap: 8px 12px; align-items: center; margin-bottom: 28px; }
.create-form label { grid-column: 1 / -1; font-weight: 600; }
input { min-width: 0; height: 42px; padding: 8px 11px; border: 1px solid #aeb8c9; border-radius: 6px; font: inherit; }
button { min-height: 42px; padding: 8px 15px; border: 0; border-radius: 6px; background: #3159a5; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #244783; }
button:focus-visible, input:focus-visible, a:focus-visible { outline: 3px solid #91b7ff; outline-offset: 2px; }
.project-list { display: grid; gap: 10px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 16px; border: 1px solid #dce1eb; border-radius: 8px; background: white; font-weight: 600; }
.alert { margin: 0 0 16px; color: #9c2424; }
@media (max-width: 480px) { .create-form { grid-template-columns: 1fr; } .create-form label { grid-column: auto; } .project-row { align-items: flex-start; flex-direction: column; } }
